// Language Detection using simple heuristics
const text = $input.first().json.user_text || '';

// Language patterns
const patterns = {
  ar: /[\u0600-\u06FF\u0750-\u077F]/,  // Arabic
  fa: /[\u0600-\u06FF]/,                // Persian (shares Arabic script)
  zh: /[\u4E00-\u9FFF]/,                // Chinese
  ja: /[\u3040-\u309F\u30A0-\u30FF]/,  // Japanese
  ko: /[\uAC00-\uD7AF]/,                // Korean
  ru: /[\u0400-\u04FF]/,                // Russian/Cyrillic
  hi: /[\u0900-\u097F]/,                // Hindi
  th: /[\u0E00-\u0E7F]/,                // Thai
};

let detected_language = 'en'; // Default to English
let confidence = 0.5;

for (const [lang, pattern] of Object.entries(patterns)) {
  if (pattern.test(text)) {
    detected_language = lang;
    confidence = 0.9;
    break;
  }
}

// Check for common English patterns if no script detected
if (detected_language === 'en') {
  const commonEnglish = /\b(the|is|are|have|has|what|how|when|where|why|can|could|would|please|thanks|thank|hello|hi|help)\b/i;
  if (commonEnglish.test(text)) {
    confidence = 0.85;
  }
}

// Use user's profile language as fallback
const userLang = $input.first().json.user?.language;
if (confidence < 0.7 && userLang) {
  detected_language = userLang;
  confidence = 0.6;
}

return [{
  ...$input.first().json,
  detected_language,
  language_confidence: confidence
}];

// Parse sentiment analysis result
let input = {};
try {
  input = $('Language Detector').item.json || {};
} catch (e) {
  input = $input.first().json || {};
}
const sentimentRaw = $input.first().json.text || $input.first().json.response || '{}';

let sentiment = { sentiment: 'neutral', score: 0, is_urgent: false, confidence: 0.5 };

try {
  // Extract JSON from response (handle markdown code blocks)
  let jsonStr = sentimentRaw;
  const jsonMatch = sentimentRaw.match(/```json?\s*([\s\S]*?)```/) || sentimentRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1] || jsonMatch[0];
  }
  sentiment = JSON.parse(jsonStr.trim());
} catch (e) {
  // Fallback: keyword-based sentiment
  const text = input.user_text.toLowerCase();
  if (/angry|furious|terrible|worst|scam|fraud|steal|ridiculous/i.test(text)) {
    sentiment = { sentiment: 'angry', score: -0.8, is_urgent: true, confidence: 0.7 };
  } else if (/frustrated|annoyed|disappointed|upset|problem|issue|not working/i.test(text)) {
    sentiment = { sentiment: 'frustrated', score: -0.5, is_urgent: false, confidence: 0.7 };
  } else if (/urgent|asap|immediately|emergency|critical|help now/i.test(text)) {
    sentiment = { sentiment: 'urgent', score: -0.3, is_urgent: true, confidence: 0.8 };
  } else if (/thank|great|excellent|amazing|love|happy|pleased/i.test(text)) {
    sentiment = { sentiment: 'positive', score: 0.7, is_urgent: false, confidence: 0.7 };
  }
}

return [{
  ...input,
  sentiment: sentiment.sentiment,
  sentiment_score: sentiment.score,
  is_urgent: sentiment.is_urgent,
  sentiment_confidence: sentiment.confidence
}];

// Parse intent classification result
let input = {};
try {
  input = $('Parse Sentiment').item.json || {};
} catch (e) {
  input = $input.first().json || {};
}
const intentRaw = $input.first().json.text || $input.first().json.response || '{}';

let intent = { intent: 'general_chat', confidence: 0.5, sub_intent: null };

try {
  let jsonStr = intentRaw;
  const jsonMatch = intentRaw.match(/```json?\s*([\s\S]*?)```/) || intentRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1] || jsonMatch[0];
  }
  intent = JSON.parse(jsonStr.trim());
} catch (e) {
  // Fallback keyword-based intent
  const text = input.user_text.toLowerCase();
  if (/balance|equity|margin|account.*status|my account/i.test(text)) {
    intent = { intent: 'account_inquiry', confidence: 0.8 };
  } else if (/position|trade|order|buy|sell|lot|pip/i.test(text)) {
    intent = { intent: 'trading_question', confidence: 0.8 };
  } else if (/deposit|withdraw|transfer|fund|payment/i.test(text)) {
    intent = { intent: 'deposit_withdrawal', confidence: 0.85 };
  } else if (/price|market|eurusd|gold|bitcoin|forecast/i.test(text)) {
    intent = { intent: 'market_analysis', confidence: 0.8 };
  } else if (/human|agent|person|manager|supervisor|speak.*someone/i.test(text)) {
    intent = { intent: 'escalation_request', confidence: 0.95 };
  } else if (/document|kyc|verify|passport|id|proof/i.test(text)) {
    intent = { intent: 'document_verification', confidence: 0.85 };
  } else if (/bonus|promotion|offer|referral/i.test(text)) {
    intent = { intent: 'promotions', confidence: 0.8 };
  } else if (/login|password|platform|mt4|mt5|not working|error|crash/i.test(text)) {
    intent = { intent: 'technical_support', confidence: 0.8 };
  } else if (/complaint|unhappy|problem|issue|terrible|disappointed/i.test(text)) {
    intent = { intent: 'complaint', confidence: 0.75 };
  }
}

return [{
  ...input,
  intent: intent.intent,
  intent_confidence: intent.confidence,
  sub_intent: intent.sub_intent || null
}];

// Smart Router & Prompt Builder v2 - context-aware domain routing
function pickNodeItem(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!items || items.length === 0) return {};

    const pairedItem = $input.first().pairedItem;
    if (pairedItem && pairedItem.item && pairedItem.item.length > 0) {
      const sourceIndex = pairedItem.item[0].index || 0;
      return items[sourceIndex]?.json || items[0].json || {};
    }

    return items[0].json || {};
  } catch (e) {
    return {};
  }
}

const context = (() => {
  const contextual = pickNodeItem('Contextual Intent Resolver');
  if (Object.keys(contextual).length > 0) return contextual;
  const parseIntent = pickNodeItem('Parse Intent');
  if (Object.keys(parseIntent).length > 0) return parseIntent;
  return $input.first().json || {};
})();

const dbConfig = $input.first().json || {};
const userText = String(context.user_text || context.message_text || '').trim();
const effectiveIntent = String(context.effective_intent || context.intent || 'general_chat');
const intentConfidence = Number(context.intent_confidence || 0);
const clarificationNeeded = Boolean(context.clarification_needed);

const routeByIntent = {
  account_inquiry: 'account',
  trading_question: 'trading',
  deposit_withdrawal: 'funding',
  market_analysis: 'market',
  technical_support: 'support',
  document_verification: 'support',
  promotions: 'support',
  complaint: 'support',
  escalation_request: 'support',
  general_chat: 'support'
};

const toolMapByRoute = {
  account: ['get_account_summary'],
  trading: ['get_open_positions', 'get_trade_history', 'calculate_trading_scenarios'],
  funding: ['get_transactions'],
  market: ['get_market_prices', 'get_market_news', 'get_economic_calendar'],
  support: ['get_platform_status', 'get_document_status', 'get_promotions', 'search_faq', 'submit_support_ticket', 'schedule_callback', 'perform_risk_assessment'],
  clarification: []
};

let routeGroup = String(context.route_group || routeByIntent[effectiveIntent] || 'support');
if (clarificationNeeded) routeGroup = 'clarification';

const scopePatterns = [
  /\b(balance|equity|margin|account|wallet|login|account type|account status)\b/i,
  /\b(trade|trading|position|order|lot|pip|open position|history)\b/i,
  /\b(deposit|withdraw|withdrawal|transfer|payment|funding)\b/i,
  /\b(mt4|mt5|platform|server|connection|terminal|password)\b/i,
  /\b(kyc|verify|verification|document|passport|id|proof)\b/i,
  /\b(promotion|bonus|offer|referral|campaign)\b/i,
  /\b(price|market|news|calendar|nfp|fomc|rates|eurusd|xauusd|gold|bitcoin|btc|eth|forex)\b/i,
  /\b(agent|human|manager|supervisor|support|ticket|callback)\b/i,
  /\b(cms prime|broker|spread|commission|leverage)\b/i
];

const inScopeByIntent = new Set([
  'account_inquiry',
  'trading_question',
  'technical_support',
  'complaint',
  'deposit_withdrawal',
  'market_analysis',
  'document_verification',
  'promotions',
  'escalation_request',
  'general_chat'
]);

let in_scope = true;
if (clarificationNeeded) {
  in_scope = true;
} else if (!userText) {
  in_scope = false;
} else if (!scopePatterns.some((r) => r.test(userText))) {
  in_scope = inScopeByIntent.has(effectiveIntent) && intentConfidence >= 0.55;
}

const allowed_tools = Array.isArray(context.allowed_tools) && context.allowed_tools.length > 0
  ? context.allowed_tools
  : (toolMapByRoute[routeGroup] || []);

const requires_tools = in_scope && !clarificationNeeded && allowed_tools.length > 0;

const refusal_message = "I don't have enough knowledge about that. I can only help with CMS Prime account, trading, platform, funding, verification, promotions, and market tools.";
const safe_fallback_message = "I couldn't retrieve reliable data right now. Please try again or contact support.";
const router_status = userText ? 'ok' : 'degraded';

const shouldEscalate = (() => {
  if (!in_scope || clarificationNeeded) return { escalate: false, reason: null };
  if (effectiveIntent === 'escalation_request') return { escalate: true, reason: 'user_requested' };
  if (context.sentiment_score < -0.6 && context.sentiment === 'angry') return { escalate: true, reason: 'negative_sentiment' };
  if (context.user?.isVip && effectiveIntent === 'complaint') return { escalate: true, reason: 'vip_complaint' };
  if ((dbConfig.recent_escalations || 0) >= 3) return { escalate: true, reason: 'recurring_issues' };
  return { escalate: false, reason: null };
})();

const routeGuidance = {
  account: 'Use only account tools. If question is ambiguous, ask a focused account clarification.',
  trading: 'Use only trading tools. Do not use funding or market tools unless the user switches topic.',
  funding: 'Use only transactions tool for deposit/withdrawal/transfer requests.',
  market: 'Use only market tools and include uncertainty-safe language.',
  support: 'Use only support tools and offer escalation when needed.',
  clarification: 'Ask one short clarification question and do not call tools.'
};

const user = context.user || {};
const profile = {
  firstName: user.firstName || '',
  lastName: user.lastName || '',
  fullName: user.fullName || [user.firstName, user.lastName].filter(Boolean).join(' ').trim(),
  vip: Boolean(user.isVip || dbConfig.is_vip),
  preferredLanguage: String(dbConfig.preferred_language || user.language || context.detected_language || 'en'),
  accountStatus: String(user.status || user.tradingStatus || 'unknown'),
  verified: user.verified ?? null,
  country: user.country || null,
  clientId: user.id || null
};

const allowedToolsLabel = allowed_tools.length > 0 ? allowed_tools.join(', ') : 'none';
const personalization = [
  'User profile:',
  'name=' + (profile.fullName || 'Valued Client') + ',',
  'vip=' + (profile.vip ? 'true' : 'false') + ',',
  'preferred_language=' + profile.preferredLanguage + ',',
  'account_status=' + profile.accountStatus + ',',
  'verified=' + String(profile.verified)
].join(' ');

const basePrompt = [
  'You are Alex from CMS Prime Support.',
  'Only use tools allowed for this turn.',
  'Never guess, infer, or fabricate facts.',
  'If tool data is missing, reply exactly: "' + safe_fallback_message + '".',
  'If request is out of scope, reply exactly: "' + refusal_message + '".',
  personalization
].join(' ');

const greetingInstruction = context.greeting_reset_required
  ? 'Session timed out. Start this turn with one short fresh greeting, then continue with the answer.'
  : 'Do not repeat greeting in every turn.';

const system_prompt = [
  basePrompt,
  'Route: ' + routeGroup + '.',
  'Effective intent: ' + effectiveIntent + '.',
  'Allowed tools: ' + allowedToolsLabel + '.',
  routeGuidance[routeGroup] || routeGuidance.support,
  greetingInstruction,
  clarificationNeeded ? 'Clarification is required for this turn.' : ''
].filter(Boolean).join(' ');

return [{
  ...context,
  user_text: userText,
  intent: context.intent || effectiveIntent,
  effective_intent: effectiveIntent,
  intent_confidence: intentConfidence,
  system_prompt,
  user_profile: profile,
  selected_persona: dbConfig.active_persona || 'friendly_support',
  should_escalate: shouldEscalate.escalate,
  escalation_reason: shouldEscalate.reason,
  db_config: dbConfig,
  in_scope,
  requires_tools,
  route_group: routeGroup,
  allowed_tools,
  primary_tool: allowed_tools[0] || null,
  follow_up_inherited: Boolean(context.follow_up_inherited),
  clarification_needed: clarificationNeeded,
  clarification_question: context.clarification_question || 'Do you mean account details, trading positions, or recent transactions?',
  routing_reason: context.routing_reason || (clarificationNeeded ? 'clarification_required' : 'classified_route'),
  session_expired: Boolean(context.session_expired),
  greeting_reset_required: Boolean(context.greeting_reset_required),
  refusal_message,
  safe_fallback_message,
  router_status
}];

function pickNodeItem(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!items || items.length === 0) return {};

    const pairedItem = $input.first().pairedItem;
    if (pairedItem && pairedItem.item && pairedItem.item.length > 0) {
      const sourceIndex = pairedItem.item[0].index || 0;
      return items[sourceIndex]?.json || items[0].json || {};
    }

    return items[0].json || {};
  } catch (e) {
    return {};
  }
}

const inputItem = $input.first().json || {};
const smartRouterContext = pickNodeItem('Smart Router & Prompt Builder');
const registrationContext = pickNodeItem('Registration Context Builder');
const extracted = pickNodeItem('Extract User Identifiers');
const normalized = pickNodeItem('Channel Normalizer');

const selectedContext = Object.keys(smartRouterContext).length > 0
  ? smartRouterContext
  : Object.keys(registrationContext).length > 0
    ? registrationContext
    : inputItem;

const context = { ...normalized, ...extracted, ...selectedContext, ...inputItem };

let response = String(inputItem.output || inputItem.text || context.output || context.text || '').trim();
const complianceFlags = [];

if (context.in_scope === false) {
  response = String(context.refusal_message || "I don't have enough knowledge about that. I can only help with CMS Prime account, trading, platform, funding, verification, promotions, and market tools.");
  complianceFlags.push('Forced out-of-scope refusal');
}

if (context.clarification_needed === true) {
  response = String(context.clarification_question || 'Could you clarify what you need: account details, trading positions, or transactions?');
  complianceFlags.push('Clarification enforced before factual answer');
}

if (!response) {
  response = String(context.safe_fallback_message || "I couldn't retrieve reliable data right now. Please try again or contact support.");
  complianceFlags.push('Applied empty-response fallback');
}

const uncertainPattern = /\b(i think|probably|likely|maybe|generally|typically|usually|it seems)\b/i;
if (context.requires_tools === true && uncertainPattern.test(response) && context.clarification_needed !== true) {
  response = String(context.safe_fallback_message || "I couldn't retrieve reliable data right now. Please try again or contact support.");
  complianceFlags.push('Replaced uncertain factual response with fallback');
}

const prohibited = [
  { pattern: /guaranteed.*profit/gi, replacement: 'potential returns (not guaranteed)' },
  { pattern: /you will.*make money/gi, replacement: 'you may see returns' },
  { pattern: /risk.?free/gi, replacement: 'with managed risk' },
  { pattern: /100%.*safe/gi, replacement: 'with appropriate risk management' },
  { pattern: /can'?t lose/gi, replacement: 'with proper risk management' },
  { pattern: /easy money/gi, replacement: 'trading opportunities' },
  { pattern: /get rich/gi, replacement: 'build wealth over time' }
];
for (const rule of prohibited) {
  if (rule.pattern.test(response)) {
    complianceFlags.push('Replaced: ' + rule.pattern.toString());
    response = response.replace(rule.pattern, rule.replacement);
  }
}

const tradingKeywords = /\b(trade|trading|position|buy|sell|invest|profit|loss|market|forex|cfd|leverage)\b/i;
const hasDisclaimer = /risk|disclaimer|not.*advice|past performance/i.test(response);
if (tradingKeywords.test(response) && !hasDisclaimer && response.length > 100 && context.in_scope !== false && context.clarification_needed !== true) {
  response += '\n\n_Trading involves risk. Past performance is not indicative of future results. This is not financial advice._';
  complianceFlags.push('Added risk disclaimer');
}

const aiClaimPattern = /I('m| am) (an? )?(AI|artificial intelligence|bot|chatbot|language model|machine)/gi;
if (aiClaimPattern.test(response)) {
  response = response.replace(aiClaimPattern, "I'm Alex from CMS Prime Support");
  complianceFlags.push('Replaced AI claim');
}

const normalizedSessionId = String(
  context.session_id ||
  context.sessionId ||
  context.metadata?.chat_id ||
  ''
).trim();

const normalizedChannel = String(
  context.channel ||
  context.metadata?.source ||
  ''
).trim();

let normalizedUserPhone = String(
  context.user_phone ||
  context.user_email ||
  ''
).trim();

if (!normalizedUserPhone && normalizedChannel === 'telegram') {
  const tgId = context.metadata?.user_id || context.metadata?.chat_id || normalizedSessionId;
  if (tgId) normalizedUserPhone = 'telegram:' + tgId;
}

const normalizedUserText = String(
  context.user_text ||
  context.message_text ||
  ''
).trim();

return [{
  ...context,
  user_phone: normalizedUserPhone,
  channel: normalizedChannel,
  session_id: normalizedSessionId,
  sessionId: normalizedSessionId,
  user_text: normalizedUserText,
  message_text: normalizedUserText,
  original_response: inputItem.output || inputItem.text || context.output || context.text || '',
  filtered_response: response,
  compliance_flags: complianceFlags
}];

// Handle escalation path
const context = $input.first().json;
const reason = context.escalation_reason;

let escalationMessage = '';

switch (reason) {
  case 'user_requested':
    escalationMessage = `I understand you'd like to speak with a human agent. Let me connect you with one of our specialists who can provide more personalized assistance.\n\nIn the meantime, I'm creating a priority support ticket so our team has all the context they need.`;
    break;
  case 'negative_sentiment':
    escalationMessage = `I can see you're having a frustrating experience, and I'm really sorry about that. I want to make sure you get the best possible help, so I'm escalating this to a senior support specialist who will reach out to you shortly.\n\nIs there anything specific you'd like me to pass along to them?`;
    break;
  case 'vip_complaint':
    escalationMessage = `As a valued VIP client, your satisfaction is our top priority. I'm immediately escalating this to your dedicated account manager who will personally follow up with you.\n\nThey will contact you within the next hour.`;
    break;
  case 'recurring_issues':
    escalationMessage = `I notice you've had to reach out about issues multiple times recently, and I apologize that we haven't fully resolved things. I'm escalating this to our senior support team for a comprehensive review of your account.\n\nSomeone will contact you within 2 hours.`;
    break;
  default:
    escalationMessage = `I'm connecting you with a human specialist who can better assist you. They'll have full context of our conversation.`;
}

return [{
  ...context,
  output: escalationMessage,
  escalation_initiated: true
}];

// Preserve context data from previous nodes
// Get original data from Compliance Filter (which has filtered_response, output, etc.)
let originalData = {};
try {
  const complianceItems = $('Compliance Filter').all();
  if (complianceItems && complianceItems.length > 0) {
    const pairedItem = $input.first().pairedItem;
    if (pairedItem && pairedItem.item && pairedItem.item.length > 0) {
      const sourceIndex = pairedItem.item[0].index || 0;
      originalData = complianceItems[sourceIndex]?.json || complianceItems[0].json || {};
    } else {
      originalData = complianceItems[0].json || {};
    }
  } else {
    originalData = $('Compliance Filter').item.json || {};
  }
} catch (e) {
  // Fallback: use current input (from DB - Update Session)
  originalData = $input.first().json || {};
}

// Get session update result
const sessionResult = $input.first().json || {};

// Merge: prioritize original data (has filtered_response, output, etc.)
return [{
  ...originalData,
  session_updated: true,
  // Update session-specific fields from DB result if available
  session_id: sessionResult.session_id || originalData.session_id,
  user_phone: sessionResult.user_phone || originalData.user_phone,
  channel: sessionResult.channel || originalData.channel
}];

// Format final response based on channel
const context = $input.first().json;
const channel = context.channel;
let response = context.filtered_response || context.output || 'I apologize, but I encountered an issue. Please try again or contact support.';

// Channel-specific formatting
if (channel === 'whatsapp') {
  // WhatsApp formatting (limited markdown)
  response = response
    .replace(/\*\*([^*]+)\*\*/g, '*$1*')  // Bold
    .replace(/^- /gm, '• ');               // Bullet points
}
else if (channel === 'telegram') {
  // Telegram supports HTML
  response = response
    .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
    .replace(/\*([^*]+)\*/g, '<i>$1</i>')
    .replace(/_([^_]+)_/g, '<i>$1</i>');
}
else if (channel === 'email') {
  // Email - add signature
  response += `\n\n---\nBest regards,\nAlex\nCMS Prime Support Team\n\nThis is an automated response. For urgent matters, please call +971 4 xxx xxxx.`;
}

return [{
  output: response,
  channel: channel,
  session_id: context.session_id,
  user_phone: context.user_phone,
  metadata: context.metadata,
  message_type: context.message_type || 'text'
}];

const current = $input.first().json || {};

function pickNodeItem(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!items || items.length === 0) return {};

    const pairedItem = $input.first().pairedItem;
    if (pairedItem && pairedItem.item && pairedItem.item.length > 0) {
      const sourceIndex = pairedItem.item[0].index || 0;
      return items[sourceIndex]?.json || items[0].json || {};
    }

    return items[0].json || {};
  } catch (e) {
    return {};
  }
}

const extracted = pickNodeItem('Extract User Identifiers');
const normalized = pickNodeItem('Channel Normalizer');
const merged = { ...normalized, ...extracted, ...current };

const channel = String(merged.channel || normalized.channel || '').trim();
const sessionId = String(
  merged.session_id ||
  merged.sessionId ||
  normalized.session_id ||
  normalized.sessionId ||
  (channel === 'telegram' ? normalized.metadata?.chat_id : '') ||
  ''
).trim();

let userPhone = String(merged.user_phone || extracted.user_phone || '').trim();
const userEmail = String(merged.user_email || extracted.user_email || '').trim();

if (!userPhone && channel === 'telegram') {
  const tgId = normalized.metadata?.user_id || normalized.metadata?.chat_id || sessionId;
  if (tgId) userPhone = `telegram:${tgId}`;
}

const messageText = String(
  merged.user_text ||
  merged.message_text ||
  normalized.message_text ||
  current.user_text ||
  current.message_text ||
  ''
).trim();

return [{
  ...merged,
  channel,
  user_phone: userPhone,
  user_email: userEmail,
  user_text: messageText,
  message_text: messageText,
  session_id: sessionId,
  sessionId,
  registration_in_progress: true,
  registration_context: merged.registration_context || {},
  auth_lookup_failed: true
}];

// Contextual Intent Resolver (with pending clarification support + session timeout reset)
function parseIsoDate(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}

function mapClarificationToIntent(text) {
  const t = String(text || '').toLowerCase();
  if (/\b(account|balance|wallet|equity|margin)\b/.test(t)) return 'account_inquiry';
  if (/\b(position|positions|trade|trading|order|history)\b/.test(t)) return 'trading_question';
  if (/\b(transaction|transactions|deposit|withdraw|withdrawal|fund|funding|pending|approved|transfer)\b/.test(t)) return 'deposit_withdrawal';
  if (/\b(price|market|news|calendar|gold|eurusd|btc|bitcoin)\b/.test(t)) return 'market_analysis';
  if (/\b(document|kyc|verify|verification|promo|promotion|ticket|support|callback)\b/.test(t)) return 'technical_support';
  return null;
}

let parsed = {};
try {
  parsed = $('Parse Intent').item.json || {};
} catch (e) {
  parsed = $input.first().json || {};
}

const state = $input.first().json || {};
const userText = String(parsed.user_text || parsed.message_text || '').trim();
const words = userText ? userText.split(/\s+/).length : 0;
const rawIntent = String(parsed.intent || 'general_chat');
const rawSubIntent = parsed.sub_intent || null;
const intentConfidence = Number(parsed.intent_confidence || 0);

const followUpPattern = /\b(and|also|what about|last one|pending|approved|this one|that one|same|again|status)\b/i;
const follow_up_detected = words > 0 && words <= 8 && followUpPattern.test(userText);

const lastTurnAt = parseIsoDate(state.last_turn_at);
const minutesSinceLastTurn = lastTurnAt ? ((Date.now() - lastTurnAt.getTime()) / (1000 * 60)) : null;

const SESSION_TIMEOUT_MINUTES = 240; // 4h
const session_expired = Boolean(
  minutesSinceLastTurn !== null &&
  minutesSinceLastTurn > SESSION_TIMEOUT_MINUTES
);

const canInherit = Boolean(
  !session_expired &&
  follow_up_detected &&
  state.last_intent &&
  minutesSinceLastTurn !== null &&
  minutesSinceLastTurn <= 30
);

const pendingClarification = Boolean(state.pending_clarification);
const clarificationExpiresAt = parseIsoDate(state.clarification_expires_at);
const pendingClarificationActive = Boolean(
  !session_expired &&
  pendingClarification &&
  (!clarificationExpiresAt || clarificationExpiresAt.getTime() > Date.now())
);

let effective_intent = rawIntent;
let follow_up_inherited = false;
let clarification_needed = false;
let routing_reason = session_expired ? 'session_timeout_reset' : 'classifier_confident';
let clarification_question = 'Could you clarify what you mean? For example: account details, open positions, or recent transactions.';
let pending_clarification = false;
let clarification_context = {};
let greeting_reset_required = session_expired;

if (pendingClarificationActive) {
  const mappedIntent = mapClarificationToIntent(userText);
  if (mappedIntent) {
    effective_intent = mappedIntent;
    follow_up_inherited = true;
    clarification_needed = false;
    pending_clarification = false;
    clarification_context = {};
    routing_reason = 'resolved_pending_clarification';
  } else {
    clarification_needed = true;
    pending_clarification = true;
    clarification_context = {
      ...(state.clarification_context || {}),
      attempts: Number(state.clarification_context?.attempts || 0) + 1
    };
    routing_reason = 'pending_clarification_unresolved';
  }
} else if (intentConfidence >= 0.72) {
  effective_intent = rawIntent;
  routing_reason = session_expired ? 'session_timeout_reset' : 'classifier_confident';
} else if (canInherit) {
  effective_intent = String(state.last_intent);
  follow_up_inherited = true;
  routing_reason = 'follow_up_inherited';
} else {
  clarification_needed = true;
  pending_clarification = true;
  clarification_context = {
    source_intent: rawIntent,
    source_confidence: intentConfidence,
    asked_at: new Date().toISOString()
  };
  routing_reason = session_expired ? 'session_timeout_reset_needs_clarification' : 'low_confidence_needs_clarification';
}

const routeByIntent = {
  account_inquiry: 'account',
  trading_question: 'trading',
  deposit_withdrawal: 'funding',
  market_analysis: 'market',
  technical_support: 'support',
  document_verification: 'support',
  promotions: 'support',
  complaint: 'support',
  escalation_request: 'support',
  general_chat: 'support'
};

const toolMapByRoute = {
  account: ['get_account_summary'],
  trading: ['get_open_positions', 'get_trade_history', 'calculate_trading_scenarios'],
  funding: ['get_transactions'],
  market: ['get_market_prices', 'get_market_news', 'get_economic_calendar'],
  support: ['get_platform_status', 'get_document_status', 'get_promotions', 'search_faq', 'submit_support_ticket', 'schedule_callback', 'perform_risk_assessment'],
  clarification: []
};

const route_group = clarification_needed
  ? 'clarification'
  : (routeByIntent[effective_intent] || 'support');

const allowed_tools = toolMapByRoute[route_group] || [];

return [{
  ...parsed,
  routing_state: {
    last_intent: state.last_intent || null,
    last_route_group: state.last_route_group || null,
    last_turn_at: state.last_turn_at || null,
    pending_clarification: pendingClarification,
    clarification_context: state.clarification_context || null,
    clarification_expires_at: state.clarification_expires_at || null
  },
  intent_confidence: intentConfidence,
  effective_intent,
  follow_up_detected,
  follow_up_inherited,
  route_group,
  allowed_tools,
  clarification_needed,
  clarification_question,
  pending_clarification,
  clarification_context,
  clarification_ttl_minutes: 10,
  routing_reason,
  session_expired,
  session_timeout_minutes: SESSION_TIMEOUT_MINUTES,
  greeting_reset_required,
  sub_intent: rawSubIntent,
  session_id: parsed.session_id || parsed.sessionId || state.input_session_id || '',
  sessionId: parsed.sessionId || parsed.session_id || state.input_session_id || ''
}];
